import { lazy, Suspense, useMemo, useRef } from 'react';
import { cn } from '@/lib/utils';
import { Message } from '@/types/chat';
// CV-061 — ghost text overlay (texto fantasma)
import { GhostTextOverlay, GhostTextHint } from '@/components/copilot/GhostTextOverlay';
// CV-063..070 — painel RADAR da Fase 7 (respostas sugeridas, ditado, sugestão de anexo)
import { RadarPhase7Panel } from '@/components/copilot/RadarPhase7Panel';
import { RadarPhase8to15Panel } from '@/components/copilot/RadarPhase8to15Panel';
import type { QuickReplyTemplate } from '@/hooks/chat/useQuickReplies';
import { Button } from '@/components/ui/button';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { AnimatePresence, motion } from 'framer-motion';
import { RichTextToolbar } from './RichTextToolbar';
import { AIRewriteButton } from './AIRewriteButton';
import { MentionAutocomplete, useMentions } from './MentionAutocomplete';
import { MarkdownPreview } from './MarkdownPreview';
import { SlashCommands, SlashCommand } from '../SlashCommands';
import { AudioRecorder } from '../AudioRecorder';
import { FileUploaderRef } from '../FileUploader';
import { SecondaryToolbar, TertiaryToolsMenu } from './ChatInputToolbars';
import { StickerPicker } from '../StickerPicker';
import { CustomEmojiPicker } from '../CustomEmojiPicker';
import { RichTextToggle } from './RichTextToolbar';
import { FileUploader } from '../FileUploader';
import { QuickActionChips } from './QuickActionChips';
import { Send, Mic, Check, Camera, Loader2, Plus } from 'lucide-react';
import { toast } from '@/hooks/ui/use-toast';
import { InputPreviewBars } from './InputPreviewBars';
import { useChatInputLogic, setNativeValue } from './useChatInputLogic';
import { ConnectionHealthBanner } from './ConnectionHealthBanner';
import { useConnectionHealthBanner } from '@/hooks/inbox/useConnectionHealthBanner';

// CV-051..060 — painel RADAR ao vivo (Fases 4-6), sob demanda. Sem sessao do motor
// (capacidade ai.capability.copilot_live desligada) ele nao renderiza nada.
const RadarLive = lazy(() => import('@/components/inbox/copilot/RadarLive'));

interface QuickReplyItem {
  id: string;
  title: string;
  shortcut: string;
  content: string;
  category: string;
}

interface ChatInputAreaProps {
  inputValue: string;
  replyToMessage: Message | null;
  editingMessage?: Message | null;
  isRecordingAudio: boolean;
  showSlashCommands: boolean;
  contactId: string;
  contactPhone: string;
  contactName: string;
  instanceName?: string;
  onPollSent?: (poll: { name: string; options: string[]; selectableCount: number }) => void;
  onContactSent?: (contactName: string) => void;
  messages: Message[];
  quickReplies: QuickReplyItem[];
  isSending?: boolean;
  onInputChange: (e: React.ChangeEvent<HTMLTextAreaElement>) => void;
  onKeyDown: (e: React.KeyboardEvent) => void;
  onBlur: () => void;
  onSend: () => void;
  onCancelReply: () => void;
  onCancelEdit?: () => void;
  onSlashCommand: (command: SlashCommand, subCommand?: string) => void;
  onCloseSlashCommands: () => void;
  onQuickReply: (reply: QuickReplyItem) => void;
  onRecordToggle: () => void;
  onAudioSend: (blob: Blob) => void;
  onAudioCancel: () => void;
  onOpenInteractiveBuilder: () => void;
  onOpenSchedule: () => void;
  onOpenLocationPicker: () => void;
  onSendSticker: (stickerUrl: string) => void;
  /** Pode ser assíncrono e falhar por rejeição (ver #350): o VoiceChangerPicker
      só descarta a prévia da voz transformada quando o envio confirma o sucesso. */
  onSendAudioMeme: (audioUrl: string) => void | Promise<void>;
  onSendCustomEmoji: (emojiUrl: string) => void;
  onOpenCatalog?: () => void;
  onSelectSuggestion: (text: string) => void;
  onSelectTemplate: (text: string) => void;
  onExternalFiles?: (files: File[]) => void;
  onPasteFiles?: (files: File[]) => void;
  signatureEnabled?: boolean;
  signatureName?: string;
  onToggleSignature?: () => void;
  fileUploaderRef: React.RefObject<FileUploaderRef | null>;
  inputRef: React.RefObject<HTMLTextAreaElement | null>;
  onOpenTransfer?: () => void;
  // CV-061 / CV-062 — ghost text (texto fantasma)
  ghostSuffix?: string;
  onGhostKeyDown?: (e: React.KeyboardEvent<HTMLTextAreaElement>) => boolean;
  /** CV-066: id da conversa para o feedback do copiloto. */
  conversationId?: string;
}

export function ChatInputArea(props: ChatInputAreaProps) {
  const {
    inputValue, replyToMessage, editingMessage, isRecordingAudio, showSlashCommands,
    contactId, contactPhone, contactName, instanceName, onPollSent, onContactSent,
    messages, quickReplies, isSending = false,
    onInputChange, onKeyDown, onBlur, onSend, onCancelReply, onCancelEdit,
    onSlashCommand, onCloseSlashCommands, onQuickReply, onRecordToggle,
    onAudioSend, onAudioCancel, onOpenInteractiveBuilder, onOpenSchedule,
    onOpenLocationPicker, onSendSticker, onSendAudioMeme,
    onSendCustomEmoji, onOpenCatalog, onSelectSuggestion, onSelectTemplate,
    onPasteFiles, signatureEnabled, signatureName, onToggleSignature,
    fileUploaderRef, inputRef, onOpenTransfer,
    // CV-061 / CV-062
    ghostSuffix = '', onGhostKeyDown,
    conversationId = '',
  } = props;

  // CV-063..070 — entradas do painel RADAR Fase 7
  const radarMessages = useMemo(
    () => messages.slice(-20).map((m) => ({ content: m.content ?? '', sender: m.sender })),
    [messages],
  );
  const radarTemplates = useMemo<QuickReplyTemplate[]>(
    () => quickReplies.map((q) => ({
      id: q.id, title: q.title, content: q.content, shortcut: q.shortcut ?? null,
      category: q.category ?? null, is_global: null, use_count: null,
      user_id: '', created_at: '', updated_at: '',
    })),
    [quickReplies],
  );
  const lastClientMessage = radarMessages.filter((m) => m.sender === 'contact').slice(-1)[0]?.content;
  // CV-071..150 — dias desde a última mensagem do cliente (risco de perda, Fase 8)
  const daysSinceLastContact = useMemo(() => {
    const ultima = [...messages].reverse().find((m) => m.sender === 'contact');
    const ts = ultima?.timestamp ? new Date(ultima.timestamp).getTime() : NaN;
    return Number.isFinite(ts) ? Math.max(0, Math.floor((Date.now() - ts) / 86_400_000)) : 0; // eslint-disable-line react-hooks/purity
  }, [messages]);

  const connectionBanner = useConnectionHealthBanner(instanceName);


  const logic = useChatInputLogic({
    inputValue, contactId, editingMessage, inputRef, fileUploaderRef, onSend, onPasteFiles,
    // R2-INB-016 (item 312): a barra recebe o par da assinatura (ligada + nome do agente) que
    // o ChatPanel já entrega, para que contador e botão contem o payload assinado.
    signatureEnabled, signatureName,
  });

  const { isOpen: mentionOpen, cursorPos: mentionCursorPos, checkForMention, handleSelect: handleMentionSelect, close: closeMention } = useMentions(inputRef);

  // Chip "Anexar" e ícone "Câmera" disparam este input oculto e entregam os
  // arquivos para o MESMO pipeline do FileUploader (handleExternalFiles já
  // existia na ref) — evita duplicar upload/preview/dialog.
  const externalFileInputRef = useRef<HTMLInputElement>(null);
  const openAttachDialog = () => externalFileInputRef.current?.click();
  const handleExternalFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files ?? []);
    if (files.length > 0) fileUploaderRef.current?.handleExternalFiles(files);
    e.target.value = '';
  };

  const tertiaryTools = useMemo(() => (
    <TertiaryToolsMenu
      contactId={contactId} instanceName={instanceName} contactPhone={contactPhone} contactName={contactName}
      messages={messages} quickReplies={quickReplies}
      onOpenInteractiveBuilder={onOpenInteractiveBuilder} onOpenLocationPicker={onOpenLocationPicker}
      onOpenSchedule={onOpenSchedule}
      onSelectSuggestion={onSelectSuggestion} onSelectTemplate={onSelectTemplate}
      onQuickReply={onQuickReply} signatureEnabled={signatureEnabled}
      signatureName={signatureName} onToggleSignature={onToggleSignature}
      onPollSent={onPollSent} onContactSent={onContactSent}
    />
  ), [contactId, instanceName, contactPhone, contactName, messages, quickReplies, onOpenInteractiveBuilder, onOpenLocationPicker, onOpenSchedule, onSelectSuggestion, onSelectTemplate, onQuickReply, onPollSent, onContactSent, signatureEnabled, signatureName, onToggleSignature]);

  return (
    <>
      <input ref={externalFileInputRef} type="file" multiple className="hidden" onChange={handleExternalFileInput} aria-hidden="true" tabIndex={-1} />

      <RichTextToolbar
        inputRef={inputRef} inputValue={inputValue}
        onInputChange={(val) => setNativeValue(inputRef, val)}
        visible={logic.showRichToolbar} onToggle={() => logic.setShowRichToolbar(!logic.showRichToolbar)}
      />

      <InputPreviewBars
        replyToMessage={replyToMessage} editingMessage={editingMessage}
        onCancelReply={onCancelReply} onCancelEdit={onCancelEdit}
      />

      {!logic.isMobile && (
        <QuickActionChips
          quickReplies={quickReplies}
          onQuickReply={onQuickReply}
          onAttach={openAttachDialog}
          onOpenSchedule={onOpenSchedule}
          onOpenTransfer={onOpenTransfer}
          moreContent={
            <div className="space-y-2">
              <SecondaryToolbar inputRef={inputRef} inputValue={inputValue}
                showRichToolbar={logic.showRichToolbar} onToggleRichToolbar={() => logic.setShowRichToolbar(!logic.showRichToolbar)}
                isRecordingAudio={isRecordingAudio} onSendSticker={onSendSticker} onSendAudioMeme={onSendAudioMeme}
                onOpenCatalog={onOpenCatalog} onAudioSend={onAudioSend}
                contactName={contactName} onVoiceDictation={logic.handleVoiceDictation}
              />
              <div className="border-t border-border" />
              {tertiaryTools}
            </div>
          }
        />
      )}

      {!logic.isMobile && !editingMessage && (
        <RadarPhase7Panel
          className="px-4 pt-2"
          inputValue={inputValue}
          conversationId={conversationId}
          contactId={contactId}
          contactName={contactName}
          messages={radarMessages}
          saleContext={{ contactName, lastClientMessage }}
          quickReplyTemplates={radarTemplates}
          onDraftText={(text) => setNativeValue(inputRef, text)}
        />
      )}

      {!logic.isMobile && !editingMessage && (
        <RadarPhase8to15Panel
          className="px-4 pt-2"
          lastClientMessage={lastClientMessage ?? ''}
          draftText={inputValue}
          daysSinceLastContact={daysSinceLastContact}
          clientName={contactName}
          onInsertText={(text) => setNativeValue(inputRef, text)}
        />
      )}

      {!logic.isMobile && !editingMessage && contactId && (
        <Suspense fallback={null}>
          <RadarLive
            className="px-4 pt-2"
            contactId={contactId}
            onDraftText={(text) => setNativeValue(inputRef, text)}
          />
        </Suspense>
      )}

      <div className={cn("px-4 py-3 border-t border-border bg-inbox-panel", logic.isMobile && "px-2.5 py-2 safe-area-bottom")}>
        <AnimatePresence>
          {isRecordingAudio && (
            <div className="mb-3"><AudioRecorder onSend={onAudioSend} onCancel={onAudioCancel} /></div>
          )}
        </AnimatePresence>

        <SlashCommands inputValue={inputValue} onSelectCommand={onSlashCommand} onClose={onCloseSlashCommands} isOpen={showSlashCommands} />

        {/* Regra dos três níveis (regras.md §4.2): o atendente sempre sabe que a conexão caiu. */}
        <ConnectionHealthBanner banner={connectionBanner} />

        <div className="flex items-end gap-2" role="toolbar" aria-label="Barra de mensagem">
          <div className={cn(
            "flex-1 min-w-0 relative flex items-end gap-1 rounded-xl bg-input border border-border",
            logic.isMobile ? "pl-3 pr-1 py-1" : "min-h-[52px] pl-4 pr-2"
          )}>
            <MentionAutocomplete inputValue={inputValue} cursorPosition={mentionCursorPos} onSelect={handleMentionSelect} onClose={closeMention} isOpen={mentionOpen} />

            <div className="flex-1 min-w-0 relative">
              <AnimatePresence>
                {logic.showMarkdownPreview && logic.hasText && logic.showRichToolbar && (
                  <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }}
                    className="mb-1 px-3 py-2 border border-border/50 rounded-lg bg-muted/30 text-sm max-h-[100px] overflow-y-auto">
                    <MarkdownPreview text={inputValue} className="text-foreground leading-relaxed" />
                  </motion.div>
                )}
              </AnimatePresence>

              {/* CV-061 — ghost text overlay posicionado atrás do textarea */}
              <GhostTextOverlay
                inputValue={inputValue}
                ghostSuffix={ghostSuffix}
                hidden={!ghostSuffix}
              />
              <textarea ref={inputRef} value={inputValue}
                onChange={(e) => { onInputChange(e); checkForMention(e.target.value, e.target.selectionStart ?? 0); }}
                onKeyDown={(e) => {
                  // CV-061 — intercepta Tab/Esc para o ghost text antes de repassar
                  if (onGhostKeyDown?.(e as React.KeyboardEvent<HTMLTextAreaElement>)) return;
                  onKeyDown(e);
                }}
                onBlur={onBlur} onPaste={logic.handlePaste}
                onClick={(e) => { const t = e.target as HTMLTextAreaElement; checkForMention(t.value, t.selectionStart ?? 0); }}
                placeholder={editingMessage ? "Editar mensagem..." : replyToMessage ? "Digite sua resposta..." : connectionBanner.level !== 'ok' ? "Sem conexão com o WhatsApp — o envio vai falhar até voltar" : "Digite uma mensagem… (/ para comandos, @ para mencionar)"}
                rows={1}
                className={cn(
                  "w-full bg-transparent border-0 outline-none text-sm text-foreground",
                  "placeholder:text-muted-foreground resize-none transition-all",
                  "focus:ring-0 relative z-10",
                  logic.isMobile ? "px-1 py-2.5 text-base min-h-[42px] max-h-[200px]" : "py-3.5 min-h-[52px] max-h-[200px]",
                )}
                aria-label={editingMessage ? "Editar mensagem" : replyToMessage ? "Responder mensagem" : "Digite sua mensagem"}
                aria-describedby={logic.charCount > 0 ? "char-counter" : undefined}
              />
              {logic.charCount > 100 && (
                <span id="char-counter" className={cn("absolute bottom-1 right-2 text-3xs select-none pointer-events-none",
                  logic.isOverLimit ? "text-destructive font-medium" : logic.isNearLimit ? "text-warning" : "text-muted-foreground/50")}>
                  {logic.charCount}/{logic.CHAR_LIMIT}
                </span>
              )}
              {/* CV-061 — dica de atalho do ghost text */}
              <GhostTextHint
                visible={!!ghostSuffix}
                className="absolute bottom-1 left-0 pointer-events-none"
              />
            </div>

            <div className="flex items-center gap-0.5 shrink-0 pb-1.5">
              <CustomEmojiPicker onSendEmoji={onSendCustomEmoji} />
              <FileUploader ref={fileUploaderRef} instanceName={instanceName || ''} recipientNumber={contactPhone}
                contactId={contactId} connectionId={undefined}
                replyToId={replyToMessage?.id ?? null}
                onFileSelect={(file, category) => toast({ title: 'Arquivo selecionado', description: `${file.name} (${category}) será enviado.` })}
                onFileSent={() => toast({ title: 'Arquivo enviado!', description: 'O arquivo foi enviado com sucesso.' })}
              />
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button variant="ghost" size="icon" className="w-9 h-9 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted"
                    onClick={openAttachDialog} aria-label="Enviar imagem">
                    <Camera className="w-5 h-5" />
                  </Button>
                </TooltipTrigger>
                <TooltipContent side="top">Enviar imagem</TooltipContent>
              </Tooltip>
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button size="icon"
                    className={cn("w-9 h-9 rounded-lg shrink-0 touch-manipulation active:scale-95 transition-all",
                      isRecordingAudio ? "bg-destructive text-destructive-foreground hover:bg-destructive/90" : "bg-transparent text-muted-foreground hover:text-foreground hover:bg-muted")}
                    onClick={onRecordToggle} aria-label={isRecordingAudio ? "Parar gravação" : "Gravar áudio"}>
                    <Mic className={cn("w-5 h-5", isRecordingAudio && "motion-safe:animate-pulse")} />
                  </Button>
                </TooltipTrigger>
                <TooltipContent side="top">{isRecordingAudio ? 'Parar gravação' : 'Gravar áudio'}</TooltipContent>
              </Tooltip>
              {/* Ferramentas adicionais no mobile — o desktop já tem via QuickActionChips */}
              {logic.isMobile && <Popover>
                <PopoverTrigger asChild>
                  <Button variant="ghost" size="icon" className="w-9 h-9 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted shrink-0" aria-label="Mais ferramentas">
                    <Plus className="w-5 h-5" />
                  </Button>
                </PopoverTrigger>
                <PopoverContent side="top" align="end" className="w-56 p-2">
                  {tertiaryTools}
                </PopoverContent>
              </Popover>}
            </div>
          </div>

          <Tooltip>
            <TooltipTrigger asChild>
              <Button onClick={logic.handleSendWithAnimation}
                disabled={(!logic.hasText && !editingMessage) || logic.isOverLimit || isSending}
                size="icon"
                className={cn("w-11 h-11 rounded-[10px] shrink-0 disabled:opacity-40 touch-manipulation active:scale-95 transition-all",
                  "bg-primary hover:bg-primary/90 text-primary-foreground",
                  logic.sendAnimation && "motion-safe:animate-pulse")}
                aria-label={editingMessage ? "Confirmar edição" : "Enviar mensagem"}>
                {isSending ? <Loader2 className="w-[18px] h-[18px] animate-spin" /> : editingMessage ? <Check className="w-[18px] h-[18px]" /> : <Send className="w-[18px] h-[18px]" />}
              </Button>
            </TooltipTrigger>
            <TooltipContent side="top">{editingMessage ? 'Confirmar edição' : 'Enviar (Enter)'}</TooltipContent>
          </Tooltip>
        </div>

        {logic.isMobile && logic.hasText && (
          <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }}
            className="flex items-center gap-1.5 mt-1.5 overflow-x-auto scrollbar-none pb-0.5">
            <AIRewriteButton inputValue={inputValue} contactName={contactName}
              onRewrite={(newText) => setNativeValue(inputRef, newText)} />
            <RichTextToggle active={logic.showRichToolbar} onToggle={() => logic.setShowRichToolbar(!logic.showRichToolbar)} />
            <StickerPicker onSendSticker={onSendSticker} />
          </motion.div>
        )}
      </div>
    </>
  );
}

/**
 * CV-051–060 — Painel RADAR flutuante.
 * Pop-up encaixado no Chat Panel: arrastável, 3 modos, mobile bottom drawer,
 * "não perturbe", acessibilidade, atalhos de teclado, indicador de pensamento.
 */
import React, { useState, useRef, useCallback, useEffect } from 'react';
import { X, Minimize2, Maximize2, Minus, BellOff, Bell, RefreshCw, Radar } from 'lucide-react';
import { cn } from '@/lib/utils';
import { SALE_STAGE_META } from '@/data/copilot/sale-stages';
import type { RadarMode, RadarCardId } from '@/hooks/copilot/useRadarPanel';
import type { CopilotSessionState } from '@/hooks/copilot/useCopilotSession';
import type { LiveSuggestion } from '@/hooks/copilot/useLiveSuggestions';
import {
  StageCard,
  BrindeCard,
  SuggestionsCard,
  NextStepCard,
  AlertsCard,
  ProductsCard,
  DecisionMakerCard,
} from './RadarCards';

// ─── Props ────────────────────────────────────────────────
export interface RadarPanelProps {
  // State from useRadarPanel
  mode: RadarMode;
  collapsed: boolean;
  collapsedCards: RadarCardId[];
  cardOrder: RadarCardId[];
  isDnd: boolean;
  onSetMode: (m: RadarMode) => void;
  onToggleCollapsed: () => void;
  onToggleCard: (id: RadarCardId) => void;
  onEnableDnd: (conversationId?: string) => void;
  onClearDnd: () => void;

  // Data
  session: CopilotSessionState | null;
  sessionLoading: boolean;
  suggestions: LiveSuggestion[];
  suggestionsLoading: boolean;
  onUseSuggestion: (text: string) => void;
  onUseSplit?: (parts: string[]) => void;
  onRefresh?: () => void;

  // Extra derived data (passed from parent — no extra fetches here)
  nextStep?: string | null;
  alerts?: string[];
  suggestedProducts?: string[];

  conversationId?: string;
  className?: string;
}

// ─── Mode buttons ────────────────────────────────────────────────
const MODE_OPTIONS: Array<{ id: RadarMode; label: string; title: string }> = [
  { id: 'mini', label: 'Mini', title: 'Modo Mini — melhor sugestão e medidor' },
  { id: 'normal', label: 'Normal', title: 'Modo Normal — cartões' },
  { id: 'focus', label: 'Foco', title: 'Modo Foco — painel completo' },
];

// ─── Timeout para "RADAR pensando" (CV-054) ────────────────────
const THINKING_TIMEOUT_MS = 8000;

// ─── RadarPanel ──────────────────────────────────────────────
export function RadarPanel({
  mode,
  collapsed,
  collapsedCards,
  cardOrder,
  isDnd,
  onSetMode,
  onToggleCollapsed,
  onToggleCard,
  onEnableDnd,
  onClearDnd,
  session,
  sessionLoading,
  suggestions,
  suggestionsLoading,
  onUseSuggestion,
  onRefresh,
  nextStep,
  alerts = [],
  suggestedProducts = [],
  conversationId,
  className,
}: RadarPanelProps) {
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [timedOut, setTimedOut] = useState(false);
  const dragRef = useRef<{ startX: number; startY: number; initX: number; initY: number } | null>(null);
  const panelRef = useRef<HTMLDivElement>(null);

  // CV-054 — timeout para "RADAR pensando"
  useEffect(() => {
    if (!suggestionsLoading) return;
    const timer = setTimeout(() => setTimedOut(true), THINKING_TIMEOUT_MS);
    return () => {
      clearTimeout(timer);
      setTimedOut(false);
    };
  }, [suggestionsLoading]);

  // CV-055 — aria-live anuncia novas sugestões (suprimido em DND)
  const latestSuggestionText = !isDnd ? (suggestions[0]?.text ?? null) : null;

  // ─── Drag logic (CV-051) ───────────────────────────────────────────────
  const onMouseDown = useCallback((e: React.MouseEvent<HTMLElement>) => {
    if ((e.target as HTMLElement).closest('button, input, textarea')) return;
    e.preventDefault();
    dragRef.current = { startX: e.clientX, startY: e.clientY, initX: position.x, initY: position.y };
    const onMove = (ev: MouseEvent) => {
      if (!dragRef.current) return;
      setPosition({
        x: dragRef.current.initX + (ev.clientX - dragRef.current.startX),
        y: dragRef.current.initY + (ev.clientY - dragRef.current.startY),
      });
    };
    const onUp = () => {
      dragRef.current = null;
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
    };
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
  }, [position]);

  // ─── Keyboard shortcuts (CV-056) ──────────────────────────────────
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      const tecla = e.key;
      if (e.ctrlKey && e.shiftKey && tecla.toLowerCase() === 'l') {
        e.preventDefault();
        onToggleCollapsed();
      }
      // Ctrl+Alt+1..3: usar sugestão — ignorado quando RADAR está silenciado
      if (!isDnd && e.ctrlKey && e.altKey && !e.shiftKey && (tecla === '1' || tecla === '2' || tecla === '3')) {
        const idx = parseInt(tecla, 10) - 1;
        if (suggestions[idx]) {
          e.preventDefault();
          onUseSuggestion(suggestions[idx].text);
        }
      }
    };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [isDnd, onToggleCollapsed, onUseSuggestion, suggestions]);

  // ─── Mobile detection ───────────────────────────────────────────────
  const isMobile = typeof window !== 'undefined' && window.innerWidth < 768;

  // ─── Mini mode ───────────────────────────────────────────────────────
  if (collapsed) {
    return (
      <div
        ref={panelRef}
        className={cn(
          'fixed z-50 right-4 bottom-24 flex items-center gap-2 rounded-full border border-border bg-background/95 shadow-lg px-3 py-1.5 cursor-grab select-none',
          className,
        )}
        style={{ transform: `translate(${position.x}px, ${position.y}px)` }}
        onMouseDown={onMouseDown}
        role="complementary"
        aria-label="RADAR Copiloto — recolhido"
      >
        <Radar className={cn('h-4 w-4 text-primary', suggestionsLoading && 'animate-pulse')} />
        <span className="text-[11px] font-semibold text-primary">RADAR</span>
        {!isDnd && suggestions.length > 0 && (
          <span className="rounded-full bg-primary px-1.5 text-[9px] font-bold text-primary-foreground">{suggestions.length}</span>
        )}
        <button
          type="button"
          onClick={onToggleCollapsed}
          className="ml-1 text-muted-foreground hover:text-foreground"
          aria-label="Expandir painel RADAR"
        >
          <Maximize2 className="h-3 w-3" />
        </button>
      </div>
    );
  }

  // ─── Mobile bottom drawer (CV-060) ───────────────────────────────────
  if (isMobile) {
    return (
      <div
        className={cn(
          'fixed bottom-0 left-0 right-0 z-50 rounded-t-xl border-t border-border bg-background/98 shadow-2xl p-4',
          className,
        )}
        role="complementary"
        aria-label="RADAR Copiloto"
      >
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-1.5">
            <Radar className={cn('h-4 w-4 text-primary', suggestionsLoading && 'animate-pulse')} />
            <span className="text-[12px] font-bold text-primary">RADAR</span>
          </div>
          <button type="button" onClick={onToggleCollapsed} aria-label="Fechar RADAR" className="text-muted-foreground hover:text-foreground">
            <Minimize2 className="h-4 w-4" />
          </button>
        </div>
        {isDnd ? (
          <div className="flex items-center gap-1.5 text-[11px] text-muted-foreground py-2">
            <BellOff className="h-3 w-3" />
            RADAR silenciado.{' '}
            <button type="button" className="underline ml-auto" onClick={onClearDnd}>Retomar</button>
          </div>
        ) : suggestions[0] ? (
          <div
            className="rounded-lg border border-primary/20 bg-primary/5 p-3 cursor-pointer hover:bg-primary/10 transition-colors"
            onClick={() => onUseSuggestion(suggestions[0].text)}
            role="button"
            tabIndex={0}
            aria-label="Usar sugestão principal"
            onKeyDown={({ key: tecla }) => tecla === 'Enter' && onUseSuggestion(suggestions[0].text)}
          >
            <p className="text-xs leading-relaxed">{suggestions[0].text}</p>
            <p className="mt-1 text-[10px] text-primary">Toque para usar</p>
          </div>
        ) : (
          <p className="text-[11px] text-muted-foreground italic text-center py-2">
            {suggestionsLoading ? 'RADAR analisando...' : 'Aguardando momento-chave...'}
          </p>
        )}
        {!isDnd && nextStep && (
          <p className="mt-2 text-[11px] text-muted-foreground">
            <span className="font-semibold">Próximo passo:</span> {nextStep}
          </p>
        )}
      </div>
    );
  }

  // ─── Desktop floating panel ───────────────────────────────────────────
  return (
    <div
      ref={panelRef}
      className={cn(
        'fixed z-50 right-4 top-20 w-72 rounded-xl border border-border bg-background/97 shadow-2xl backdrop-blur-sm select-none',
        mode === 'mini' && 'w-60',
        mode === 'focus' && 'w-80',
        className,
      )}
      style={{ transform: `translate(${position.x}px, ${position.y}px)` }}
      role="complementary"
      aria-label="RADAR Copiloto"
    >
      {/* Header — draggable (CV-051) */}
      <div
        className="flex items-center gap-1.5 rounded-t-xl border-b border-border/60 px-3 py-2 cursor-grab active:cursor-grabbing"
        onMouseDown={onMouseDown}
      >
        <Radar className={cn('h-4 w-4 text-primary shrink-0', suggestionsLoading && !timedOut && 'animate-pulse')} />
        <span className="text-[11px] font-bold text-primary flex-1">RADAR</span>

        {/* CV-054 — indicator */}
        {!isDnd && suggestionsLoading && !timedOut && (
          <span className="flex h-1.5 w-1.5 rounded-full bg-primary animate-ping mr-1" aria-hidden="true" />
        )}

        {/* Mode selector (CV-052) */}
        <div className="flex items-center gap-0.5 rounded border border-border/60 p-0.5">
          {MODE_OPTIONS.map((m) => (
            <button
              key={m.id}
              type="button"
              title={m.title}
              onClick={(e) => { e.stopPropagation(); onSetMode(m.id); }}
              className={cn(
                'rounded px-1 text-[9px] font-medium transition-colors',
                mode === m.id ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:text-foreground',
              )}
              aria-pressed={mode === m.id}
            >
              {m.label}
            </button>
          ))}
        </div>

        {/* DND toggle (CV-058) */}
        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            if (isDnd) onClearDnd();
            else onEnableDnd(conversationId);
          }}
          className="text-muted-foreground hover:text-foreground transition-colors"
          title={isDnd ? 'Retomar RADAR' : 'Silenciar RADAR (não perturbe)'}
          aria-label={isDnd ? 'Retomar RADAR' : 'Silenciar RADAR'}
        >
          {isDnd ? <Bell className="h-3.5 w-3.5" /> : <BellOff className="h-3.5 w-3.5" />}
        </button>

        {/* Refresh */}
        {onRefresh && (
          <button
            type="button"
            onClick={(e) => { e.stopPropagation(); onRefresh(); }}
            disabled={suggestionsLoading}
            className="text-muted-foreground hover:text-foreground transition-colors disabled:opacity-40"
            aria-label="Atualizar RADAR"
          >
            <RefreshCw className={cn('h-3.5 w-3.5', suggestionsLoading && 'animate-spin')} />
          </button>
        )}

        {/* Collapse */}
        <button
          type="button"
          onClick={(e) => { e.stopPropagation(); onToggleCollapsed(); }}
          className="text-muted-foreground hover:text-foreground transition-colors"
          aria-label="Recolher painel RADAR"
        >
          <Minus className="h-3.5 w-3.5" />
        </button>
      </div>

      {/* CV-054 — timeout message */}
      {!isDnd && timedOut && (
        <div className="px-3 py-2 text-[11px] text-amber-600 dark:text-amber-400 bg-amber-500/10 border-b border-border/60">
          Não consegui analisar agora —{' '}
          <button type="button" className="underline" onClick={onRefresh}>tentar de novo</button>
        </div>
      )}

      {/* DND banner */}
      {isDnd && (
        <div className="flex items-center gap-1.5 px-3 py-1.5 text-[11px] text-muted-foreground bg-muted/40 border-b border-border/60">
          <BellOff className="h-3 w-3" />
          RADAR silenciado.{' '}
          <button type="button" className="underline ml-auto" onClick={onClearDnd}>Retomar</button>
        </div>
      )}

      {/* aria-live region (CV-055/057) — suprimido quando DND ativo */}
      <div
        aria-live="polite"
        aria-atomic="true"
        className="sr-only"
      >
        {latestSuggestionText && `Nova sugestão do RADAR: ${latestSuggestionText}`}
      </div>

      {/* Corpo do painel — não renderiza quando RADAR silenciado (CV-058) */}
      {!isDnd && (
        <>
          {/* Mini mode body */}
          {mode === 'mini' && (
            <div className="p-3 space-y-2">
              <SuggestionsCard
                suggestions={suggestions.slice(0, 1)}
                loading={suggestionsLoading}
                collapsed={false}
                onToggle={() => {}}
                onUse={onUseSuggestion}
              />
              {session && (
                <div className="flex items-center gap-2 text-[11px] text-muted-foreground">
                  <span className="rounded bg-muted px-1.5 py-0.5 font-bold">{SALE_STAGE_META[session.stage].label}</span>
                  <div className="flex gap-0.5">
                    {(['B','R','I','N','D','E'] as const).map((l) => (
                      <span key={l} className={cn('font-bold text-[10px]', session.brinde_state[l] ? 'text-primary' : 'text-muted-foreground/30')}>{l}</span>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Normal / Focus mode body */}
          {(mode === 'normal' || mode === 'focus') && (
            <div className="max-h-[calc(100vh-180px)] overflow-y-auto p-2 space-y-1.5 overscroll-contain" style={{ scrollbarWidth: 'thin' }}>
              {cardOrder.map((cardId) => {
                const isCollapsed = collapsedCards.includes(cardId);
                switch (cardId) {
                  case 'stage':
                    return (
                      <StageCard
                        key="stage"
                        stage={session?.stage ?? null}
                        temperature={session?.temperature ?? null}
                        collapsed={isCollapsed}
                        onToggle={() => onToggleCard('stage')}
                      />
                    );
                  case 'brinde':
                    return (
                      <BrindeCard
                        key="brinde"
                        brindeState={session?.brinde_state ?? null}
                        collapsed={isCollapsed}
                        onToggle={() => onToggleCard('brinde')}
                      />
                    );
                  case 'suggestions':
                    return (
                      <SuggestionsCard
                        key="suggestions"
                        suggestions={suggestions}
                        loading={suggestionsLoading}
                        collapsed={isCollapsed}
                        onToggle={() => onToggleCard('suggestions')}
                        onUse={onUseSuggestion}
                      />
                    );
                  case 'next_step':
                    return (
                      <NextStepCard
                        key="next_step"
                        nextStep={nextStep ?? null}
                        collapsed={isCollapsed}
                        onToggle={() => onToggleCard('next_step')}
                      />
                    );
                  case 'alerts':
                    return (
                      <AlertsCard
                        key="alerts"
                        alerts={alerts}
                        collapsed={isCollapsed}
                        onToggle={() => onToggleCard('alerts')}
                      />
                    );
                  case 'products':
                    return (
                      <ProductsCard
                        key="products"
                        products={suggestedProducts}
                        collapsed={isCollapsed}
                        onToggle={() => onToggleCard('products')}
                      />
                    );
                  case 'decision_maker':
                    return (
                      <DecisionMakerCard
                        key="decision_maker"
                        decisionRole={session?.decision_role ?? null}
                        stakeholders={session?.stakeholders ?? []}
                        collapsed={isCollapsed}
                        onToggle={() => onToggleCard('decision_maker')}
                      />
                    );
                  default:
                    return null;
                }
              })}
            </div>
          )}
        </>
      )}

      {/* Footer — keyboard hint (CV-056) */}
      <div className="rounded-b-xl border-t border-border/40 px-3 py-1 text-[9px] text-muted-foreground/50 flex gap-3">
        <span>Ctrl+Shift+L: abrir/fechar</span>
        {!isDnd && <span>Ctrl+Alt+1/2/3: usar sugestão</span>}
      </div>
    </div>
  );
}

/**
 * CV-032 — Sessão do Copiloto RADAR do contato aberto.
 *
 * Lê `copilot_sessions` (uma por conversa: `UNIQUE(conversation_id)`) e
 * entrega o estado no formato das telas: etapa, temperatura 0–100 e as
 * letras B·R·I·N·D·E vindas das colunas `brinde_*`.
 * Quando o contato tem mais de uma sessão (mais de uma conversa aberta),
 * retorna a mais recente por `started_at DESC`.
 * RLS: o vendedor só enxerga a própria sessão (`profile_id = auth.uid()`).
 *
 * `copilot_sessions` não está na publicação do Realtime; quem avisa que o
 * estado mudou é o insight novo (ver useLiveSuggestions → `refresh`).
 */
import { useCallback, useEffect, useState } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { isSaleStage, type SaleStage } from '@/data/copilot/sale-stages';

export type BrindeLetter = 'B' | 'R' | 'I' | 'N' | 'D' | 'E';

export interface Stakeholder {
  name: string;
  role?: string;
}

export interface CopilotSessionState {
  id: string;
  stage: SaleStage;
  temperature: number;
  brindeMeter: number;
  brinde_state: Record<BrindeLetter, string | null>;
  brinde_evidence: Record<BrindeLetter, string | null>;
  state_version: number;
  decision_role: string | null;
  occasion: string | null;
  comm_style: string | null;
  intent: string | null;
  sentiment: string | null;
  stakeholders: Stakeholder[];
  last_tick_at: string | null;
}

/** Coluna `brinde_*` e chave de evidência gravadas pelo motor, por letra. */
const LETRAS: Record<BrindeLetter, { coluna: string; evidencia: string }> = {
  B: { coluna: 'brinde_budget', evidencia: 'budget' },
  R: { coluna: 'brinde_responsible', evidencia: 'responsible' },
  I: { coluna: 'brinde_intention', evidencia: 'intention' },
  N: { coluna: 'brinde_quantity', evidencia: 'quantity' },
  D: { coluna: 'brinde_deadline', evidencia: 'deadline' },
  E: { coluna: 'brinde_delivery', evidencia: 'delivery' },
};

const COLUNAS = [
  'id', 'sale_stage', 'temperature', 'brinde_meter', 'state_version', 'last_tick_at',
  'decision_role', 'occasion', 'comm_style', 'intent', 'sentiment', 'stakeholders', 'brinde_evidence',
  ...Object.values(LETRAS).map((l) => l.coluna),
].join(', ');

function texto(v: unknown): string | null {
  if (v === null || v === undefined || v === '') return null;
  return String(v);
}

/** Converte a linha do banco no estado das telas. Exportado para teste. */
export function toCopilotSessionState(row: Record<string, unknown>): CopilotSessionState {
  const evid = (row.brinde_evidence && typeof row.brinde_evidence === 'object' ? row.brinde_evidence : {}) as Record<string, unknown>;
  const letras = Object.keys(LETRAS) as BrindeLetter[];
  const stakeholders = Array.isArray(row.stakeholders)
    ? (row.stakeholders as Array<Record<string, unknown>>)
        .filter((s) => typeof s?.name === 'string' && s.name !== '')
        .map((s) => ({ name: s.name as string, role: typeof s.role === 'string' ? s.role : undefined }))
    : [];
  return {
    id: String(row.id),
    stage: isSaleStage(row.sale_stage) ? row.sale_stage : 'novo_contato',
    temperature: typeof row.temperature === 'number' ? row.temperature : 0,
    brindeMeter: typeof row.brinde_meter === 'number' ? row.brinde_meter : 0,
    brinde_state: Object.fromEntries(letras.map((l) => [l, texto(row[LETRAS[l].coluna])])) as Record<BrindeLetter, string | null>,
    brinde_evidence: Object.fromEntries(letras.map((l) => [l, texto(evid[LETRAS[l].evidencia])])) as Record<BrindeLetter, string | null>,
    state_version: typeof row.state_version === 'number' ? row.state_version : 0,
    decision_role: texto(row.decision_role),
    occasion: texto(row.occasion),
    comm_style: texto(row.comm_style),
    intent: texto(row.intent),
    sentiment: texto(row.sentiment),
    stakeholders,
    last_tick_at: texto(row.last_tick_at),
  };
}

export interface UseCopilotSessionResult {
  session: CopilotSessionState | null;
  loading: boolean;
  refresh: () => void;
}

export function useCopilotSession(contactId: string | undefined): UseCopilotSessionResult {
  const [versao, setVersao] = useState(0);
  // Resultado guardado com a chave que o produziu: troca de contato não mostra a sessão do anterior.
  const [lido, setLido] = useState<{ chave: string; contactId: string; session: CopilotSessionState | null } | null>(null);
  const chave = contactId ? `${contactId}:${versao}` : null;

  const refresh = useCallback(() => setVersao((v) => v + 1), []);

  useEffect(() => {
    if (!contactId || !chave) return;
    let cancelado = false;
    void (async () => {
      let session: CopilotSessionState | null = null;
      try {
        const { data, error } = await supabase
          .from('copilot_sessions')
          .select(COLUNAS)
          .eq('contact_id', contactId)
          .order('started_at', { ascending: false })
          .limit(1)
          .maybeSingle();
        if (cancelado) return;
        // Erro (ex.: tabela ainda sem as colunas do motor) = sem RADAR, sem quebrar a Inbox.
        session = !error && data ? toCopilotSessionState(data as unknown as Record<string, unknown>) : null;
      } catch {
        // A consulta pode lancar (rede, cliente sem o metodo): o contrato acima e
        // "sem RADAR, sem quebrar a Inbox", e promessa rejeitada quebraria a tela.
        if (cancelado) return;
        session = null;
      }
      setLido({ chave, contactId, session });
    })();
    return () => {
      cancelado = true;
    };
  }, [contactId, chave]);

  const session = contactId && lido?.contactId === contactId ? lido.session : null;
  const loading = chave !== null && lido?.chave !== chave;
  return { session, loading, refresh };
}
